<?php require_once __DIR__.'/../config.php';require_admin();$pdo=db();$stats=[];$stats['orders']=(int)$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn();$stats['customers']=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn();$stats['products']=(int)$pdo->query('SELECT COUNT(*) FROM products WHERE active=1')->fetchColumn();$stats['revenue']=(float)$pdo->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status<>'Cancelled'")->fetchColumn();$stats['pending']=(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status='Pending'")->fetchColumn();$orders=$pdo->query('SELECT * FROM orders ORDER BY id DESC LIMIT 8')->fetchAll();$products=$pdo->query('SELECT * FROM products ORDER BY id')->fetchAll();$pageTitle='Admin Dashboard';require __DIR__.'/../includes/header.php';?><section class="section-pad"><div class="container-fluid admin-layout"><aside class="admin-sidebar"><div class="eyebrow">CONTROL CENTER</div><a class="active" href="/powervault/admin/">▦ Dashboard</a><a href="/powervault/admin/products.php">◇ Products</a><a href="/powervault/admin/inventory.php">▤ Inventory</a><a href="/powervault/admin/orders.php">⇄ Orders</a><a href="/powervault/admin/profit-loss.php">⌁ Profit & Loss</a><a href="/powervault/admin/settings.php">⚙ Settings</a><a href="/powervault/logout.php">↪ Logout</a></aside><div class="admin-content"><div class="section-heading"><div><div class="eyebrow">OVERVIEW</div><h1>Admin <span class="gradient-text">Dashboard</span></h1><p>Welcome back, <?=e(user()['name'])?>. Here's your store snapshot.</p></div><a href="/powervault/admin/products.php" class="btn btn-neon">+ Add Product</a></div><div class="stats-grid"><div class="stat-card"><span>Total Orders</span><b><?=$stats['orders']?></b><small>All order records</small></div><div class="stat-card"><span>Total Revenue</span><b><?=money($stats['revenue'])?></b><small>Non-cancelled orders</small></div><div class="stat-card"><span>Customers</span><b><?=$stats['customers']?></b><small>Registered users</small></div><div class="stat-card"><span>Active Products</span><b><?=$stats['products']?></b><small><?=$stats['pending']?> pending orders</small></div></div><div class="row g-4 mt-1"><div class="col-xl-7"><div class="dashboard-panel"><h3>Revenue Overview</h3><canvas id="salesChart" height="125"></canvas><p class="muted small mt-2">Chart uses recent order records. This is a simple order trend, not a forecast.</p></div></div><div class="col-xl-5"><div class="dashboard-panel"><h3>Quick Actions</h3><div class="quick-actions"><a href="/powervault/admin/products.php">＋ Add or edit products</a><a href="/powervault/admin/inventory.php">▤ Update inventory</a><a href="/powervault/admin/orders.php">⇄ Manage customer orders</a><a href="/powervault/admin/profit-loss.php">⌁ Record costs and expenses</a></div></div></div><div class="col-12"><div class="dashboard-panel"><div class="section-heading"><h3>Recent Orders</h3><a class="text-link" href="/powervault/admin/orders.php">View all ↗</a></div><div class="table-responsive"><table class="table pv-table"><thead><tr><th>Order</th><th>Customer</th><th>Payment</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><?=e($o['order_number'])?></td><td><?=e($o['customer_name'])?></td><td><?=e($o['payment_method'])?></td><td><?=money($o['total'])?></td><td><span class="status-pill"><?=e($o['status'])?></span></td></tr><?php endforeach; ?><?php if(!$orders): ?><tr><td colspan="5">No orders yet.</td></tr><?php endif; ?></tbody></table></div></div></div></div></div></div></section><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>fetch('/powervault/api/sales.php').then(r=>r.json()).then(d=>{const c=document.getElementById('salesChart');new Chart(c,{type:'line',data:{labels:d.labels,datasets:[{label:'Revenue (Rs.)',data:d.values,tension:.35,fill:true,borderColor:'#00c8ff',backgroundColor:'rgba(0,200,255,.10)'}]},options:{plugins:{legend:{labels:{color:'#dceeff'}}},scales:{x:{ticks:{color:'#9bb4ca'},grid:{color:'rgba(100,160,200,.1)'}},y:{ticks:{color:'#9bb4ca'},grid:{color:'rgba(100,160,200,.1)'}}}}})}).catch(()=>{});</script><?php require __DIR__.'/../includes/footer.php';?>
